import pytest
import requests
import os
import time
from uuid import uuid4

BASE_URL = os.environ.get("BASE_URL", "https://petstore.swagger.io/v2")

def test_add_pet_happy_path(session, base_url, new_pet_payload):
    """Happy path: Add a new pet with valid data."""
    url = f"{base_url}/pet"
    resp = session.post(url, json=new_pet_payload, timeout=10)
    assert resp.status_code in (200, 201), f"Unexpected status: {resp.status_code} - {resp.text}"
    data = None
    try:
        data = resp.json()
    except ValueError:
        data = {}
    assert "name" in data, f"Response missing 'name': {resp.text}"
    assert data.get("name") == new_pet_payload["name"]

def test_get_pet_by_id_happy_path(session, base_url):
    """Happy path: Create a pet and then retrieve it by ID."""
    t = int(time.time() * 1000)
    payload = {"id": t, "name": f"TestPet-{t}", "photoUrls": ["http://example.com/photo.jpg"]}
    post_resp = session.post(f"{base_url}/pet", json=payload, timeout=10)
    assert post_resp.status_code in (200, 201), f"Post failed: {post_resp.status_code} - {post_resp.text}"
    get_resp = session.get(f"{base_url}/pet/{payload['id']}", timeout=10)
    assert get_resp.status_code == 200, f"Get failed: {get_resp.status_code} - {get_resp.text}"
    try:
        data = get_resp.json()
    except ValueError:
        data = {}
    if data:
        assert data.get("id") == payload["id"] or data.get("name") == payload["name"]

def test_get_pet_by_id_not_found(session, base_url):
    """Not found: Request a non-existent pet should yield 404 or 400."""
    resp = session.get(f"{base_url}/pet/999999999999999", timeout=10)
    assert resp.status_code in (400, 404)

def test_find_pets_by_status_happy_path(session, base_url):
    """Happy path: Find pets by status (visible one value)."""
    resp = session.get(f"{base_url}/pet/findByStatus", params={"status": ["available"]}, timeout=10)
    assert resp.status_code == 200, f"Status: {resp.status_code} - {resp.text}"
    try:
        data = resp.json()
    except ValueError:
        data = []
    assert isinstance(data, list)

def test_find_pets_by_tags_happy_path(session, base_url):
    """Happy path: Find pets by tags (single tag)."""
    resp = session.get(f"{base_url}/pet/findByTags", params=[("tags", "tag1")], timeout=10)
    assert resp.status_code == 200, f"Status: {resp.status_code} - {resp.text}"
    try:
        data = resp.json()
    except ValueError:
        data = []
    assert isinstance(data, list)

def test_update_pet_happy_path(session, base_url):
    """Happy path: Update an existing pet using PUT with a modified payload."""
    t = int(time.time() * 1000)
    payload = {"id": t, "name": f"TestPet-{t}", "photoUrls": ["http://example.com/photo.jpg"]}
    post_resp = session.post(f"{base_url}/pet", json=payload, timeout=10)
    assert post_resp.status_code in (200, 201), f"Post failed: {post_resp.status_code}"
    updated = payload.copy()
    updated["name"] = payload["name"] + "-updated"
    put_resp = session.put(f"{base_url}/pet", json=updated, timeout=10)
    assert put_resp.status_code in (200, 201), f"Put failed: {put_resp.status_code}"
    get_resp = session.get(f"{base_url}/pet/{payload['id']}", timeout=10)
    if get_resp.status_code == 200:
        try:
            data = get_resp.json()
        except ValueError:
            data = {}
        if data:
            assert data.get("name") == updated["name"] or data.get("id") == payload["id"]

def test_upload_image_happy_path(session, base_url):
    """Happy path: Upload an image for a pet using multipart/form-data."""
    t = int(time.time() * 1000)
    payload = {"id": t, "name": f"TestPet-{t}", "photoUrls": ["http://example.com/photo.jpg"]}
    post_resp = session.post(f"{base_url}/pet", json=payload, timeout=10)
    assert post_resp.status_code in (200, 201), f"Post failed: {post_resp.status_code}"
    files = {'file': ('test.txt', b'sample data', 'text/plain')}
    data = {'additionalMetadata': 'metadata'}
    resp_upload = session.post(f"{base_url}/pet/{payload['id']}/uploadImage", files=files, data=data, timeout=10)
    assert resp_upload.status_code in (200, 201), f"Upload failed: {resp_upload.status_code}"
    try:
        jd = resp_upload.json()
        assert isinstance(jd, dict)
    except ValueError:
        pass

def test_delete_pet_happy_path(session, base_url):
    """Happy path: Delete a pet that was just created."""
    t = int(time.time() * 1000)
    payload = {"id": t, "name": f"TestPet-{t}", "photoUrls": ["http://example.com/photo.jpg"]}
    post_resp = session.post(f"{base_url}/pet", json=payload, timeout=10)
    assert post_resp.status_code in (200, 201), f"Post failed: {post_resp.status_code}"
    del_resp = session.delete(f"{base_url}/pet/{payload['id']}", timeout=10)
    assert del_resp.status_code in (200, 204), f"Delete failed: {del_resp.status_code}"

def test_delete_pet_not_found(session, base_url):
    """Not found: Attempt to delete a non-existent pet should respond appropriately."""
    resp = session.delete(f"{base_url}/pet/999999999999999", timeout=10)
    assert resp.status_code in (400, 404, 409)

